aparencia.css:
/* ARCANE | Gelo e cinábrio
   Substitua todo o CSS anterior em Aparência > CSS da Ficha.
   Identidade: gelo #e5f3f5, grafite #101a25, aço #1a2b3b,
   turquesa #79d9d0, vermelho #ed5b57 e violeta #baaff0.
   Sem fontes externas. O tema se aplica somente à tela.
   Paleta compartilhada pelas duas fichas. Layout refinado para a Clássica.
*/

@media screen {
  :scope#afty-ficha,
  #afty-ficha#afty-ficha {
    --arcane-gelo: #e5f3f5;
    --arcane-tinta: #172b3b;
    --arcane-vermelho: #ed5b57;
    --arcane-vermelho-escuro: #b7353e;
    --arcane-superficie: #203546;
    --arcane-divisoria: #304354;
    --afty-fundo: #101a25;
    --afty-fundo-brilho: none;
    --afty-card: #1a2b3b;
    --afty-poco: #142230;
    --afty-borda: #354c5f;
    --afty-borda-forte: #658598;
    --afty-texto: #e5f3f5;
    --afty-texto-suave: #c0d2df;
    --afty-texto-fraco: #a7bdcf;
    --afty-destaque: #79d9d0;
    --afty-destaque-texto: #c4f5ed;
    --afty-destaque-fundo: #24434d;
    --afty-pv: #ff8887;
    --afty-pe: #79d9d0;
    --afty-pvtemp: #ebc58b;
    --afty-petemp: #d4faf2;
    --afty-alma: #baaff0;
    --afty-cura: #9ddab5;
    --afty-aviso: #ebc58b;
    --afty-veu: rgb(8 15 23 / 0.82);
    --afty-raio: 10px;
    --afty-raio-peq: 5px;
    --afty-sombra: 0 3px 12px rgb(5 12 20 / 0.16);
    --afty-fonte: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
    --afty-fonte-titulo: "Bahnschrift", "Trebuchet MS", "Segoe UI", sans-serif;
    --afty-fonte-display: var(--afty-fonte-titulo);
    --afty-fonte-num: "Cascadia Mono", Consolas, "Liberation Mono", monospace;
    color-scheme: dark;
  }

  /* Cabeçalho opaco: o conteúdo nunca atravessa a leitura durante a rolagem. */
  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) header.afty-cabecalho {
    background: var(--afty-fundo);
    border-bottom-color: var(--afty-borda);
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) header.afty-cabecalho::after {
    background: none;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo {
    background: var(--afty-poco);
    border-radius: 0 0 var(--afty-raio) var(--afty-raio);
    box-shadow: inset 0 2px var(--arcane-divisoria);
    padding-inline: 0.65rem;
  }

  /* A placa clara ocupa a identidade, não a fileira inteira de controles.
     Os pigmentos claros ficam limitados à placa. */
  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-principal > div:has(> div > .afty-nome) {
    column-gap: 0.6rem;
    padding-block: 0.6rem;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-principal > div > div:has(> .afty-nome) {
    --afty-texto: var(--arcane-tinta);
    --afty-texto-suave: #38556a;
    --afty-texto-fraco: #476477;
    --afty-card: #edf7f8;
    --afty-poco: #edf7f8;
    --afty-borda: #9ab8c3;
    --afty-borda-forte: #7899a8;
    --afty-destaque: #25685f;
    --afty-destaque-texto: #1a554f;
    --afty-destaque-fundo: #cae5e2;
    --afty-aviso: #805018;
    position: relative;
    padding: 0.45rem 1.1rem 0.5rem 0.8rem;
    border-inline-start: 4px solid var(--arcane-vermelho);
    border-radius: 2px 8px 2px 8px;
    background: var(--arcane-gelo);
    color: var(--arcane-tinta);
    color-scheme: light;
  }

  /* A incisão vermelha ecoa os detalhes do rosto e do traje. */
  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-principal > div > div:has(> .afty-nome)::after {
    content: "";
    position: absolute;
    inset-block-start: 0;
    inset-inline-end: 0.5rem;
    width: 0.4rem;
    height: 1.15rem;
    background: var(--arcane-vermelho-escuro);
    clip-path: polygon(0 0, 100% 0, 75% 100%, 0 72%);
    pointer-events: none;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-nome {
    color: var(--afty-texto);
    font-family: var(--afty-fonte-titulo);
    font-size: clamp(1.55rem, 2.5vw, 2rem);
    font-weight: 650;
    letter-spacing: 0.015em;
    line-height: 1.12;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) [data-afty-compacto="sim"] .afty-nome {
    font-size: 1.25rem;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-retrato-painel {
    border: 1px solid var(--afty-borda-forte);
    border-radius: 3px 10px 3px 10px;
    box-shadow: none;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-retrato-painel::after {
    background:
      linear-gradient(var(--arcane-vermelho), var(--arcane-vermelho)) right 0.5rem top 0.5rem / 3px 2.4rem no-repeat,
      linear-gradient(var(--arcane-vermelho), var(--arcane-vermelho)) right 0.5rem top 0.5rem / 1.15rem 3px no-repeat,
      linear-gradient(var(--afty-destaque), var(--afty-destaque)) left 0.5rem bottom 0.5rem / 1.7rem 2px no-repeat,
      linear-gradient(180deg, transparent 70%, rgb(16 26 37 / 0.3));
  }

  /* Vitais: leitura direta, sem brilho artificial. Mantém a casca temporária. */
  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-vital {
    background: var(--afty-card);
    border-radius: 7px;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-vital[data-afty-vital="preparo"] {
    --afty-vital-cor: #d4e3ef;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-vital-rotulo {
    letter-spacing: 0.065em;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-vital-trilho {
    box-shadow: none;
    background: var(--afty-fundo);
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-vital-barra {
    background: var(--afty-vital-cor);
    box-shadow: none;
  }

  /* Sem largura dinâmica experimental: até quatro dígitos continuam editáveis. */
  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo .afty-vital-numero {
    width: 4ch;
    min-width: 3ch;
    font-variant-numeric: tabular-nums;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-stat {
    border-color: var(--arcane-divisoria);
    background: var(--afty-poco);
  }

  /* A navegação continua turquesa. Vermelho é identidade, não seleção. */
  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) :is(.afty-aba, .afty-subaba)[aria-selected="true"] {
    background-color: var(--afty-destaque-fundo);
    border-bottom-color: var(--afty-destaque);
    color: var(--afty-destaque-texto);
    border-radius: 5px 5px 0 0;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-card-titulo {
    color: var(--afty-texto);
    font-size: 0.8rem;
    font-weight: 650;
    letter-spacing: 0.07em;
    line-height: 1.4;
  }

  /* Recorte vermelho discreto nos quatro grupos de consulta da Clássica. */
  :is(:scope#afty-ficha, #afty-ficha#afty-ficha):not([data-afty-estrutura="g2"]) [aria-labelledby="afty-aba-pericias"] .afty-card > .afty-card-titulo {
    border-inline-start: 3px solid var(--arcane-vermelho);
    padding-inline-start: 0.55rem;
    margin-block-end: 0.65rem;
  }

  /* Linhas abertas mantêm fontes e painéis visíveis. Nunca usar overflow aqui. */
  :is(:scope#afty-ficha, #afty-ficha#afty-ficha):not([data-afty-estrutura="g2"]) :is([aria-labelledby="afty-aba-acoes"], [aria-labelledby="afty-aba-pericias"]) .afty-card .afty-linha:not([data-afty-destacada="sim"], [data-afty-alvo="sim"]) {
    background: transparent;
    border-color: transparent;
    border-bottom-color: var(--arcane-divisoria);
    border-radius: 3px;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha):not([data-afty-estrutura="g2"]) :is([aria-labelledby="afty-aba-acoes"], [aria-labelledby="afty-aba-pericias"]) .afty-linha[data-afty-destacada="sim"]:not([data-afty-alvo="sim"]) {
    border-color: var(--afty-borda);
    border-inline-start: 3px solid var(--afty-destaque);
    background: var(--afty-destaque-fundo);
    border-radius: 5px;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha):not([data-afty-estrutura="g2"]) [aria-labelledby="afty-aba-pericias"] .afty-linha {
    min-height: 2.35rem;
    padding: 0.3rem 0.55rem;
    gap: 0.45rem;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha):not([data-afty-estrutura="g2"]) [aria-labelledby="afty-aba-pericias"] .afty-linha > span:first-child {
    font-size: 0.8125rem;
    line-height: 1.35;
    font-weight: 600;
    white-space: normal;
    overflow-wrap: anywhere;
  }

  /* O botão fica DENTRO de .afty-fontes-raiz, não diretamente na linha. */
  :is(:scope#afty-ficha, #afty-ficha#afty-ficha):not([data-afty-estrutura="g2"]) [aria-labelledby="afty-aba-pericias"] .afty-linha > .afty-fontes-raiz > .afty-rolavel {
    min-width: 2.65rem;
    min-height: 1.75rem;
    padding: 0.2rem 0.4rem;
    border: 1px solid var(--afty-borda-forte);
    background: var(--afty-poco);
    color: var(--afty-texto);
    border-radius: 5px;
    font-size: 0.8125rem;
    text-align: center;
    text-decoration: none;
    white-space: nowrap;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha):not([data-afty-estrutura="g2"]) [aria-labelledby="afty-aba-pericias"] .afty-atributo:not([data-afty-alvo="sim"]) {
    padding-block: 0.5rem;
    gap: 0.25rem;
    background: var(--afty-poco);
    border-color: var(--arcane-divisoria);
    border-radius: 6px;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-atributo-rotulo {
    color: var(--afty-texto-suave);
    font-size: 0.675rem;
    letter-spacing: 0.09em;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-atributo-mod {
    min-width: 2.25rem;
    min-height: 1.5rem;
    text-align: center;
    border-radius: 4px;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-botao[data-afty-tom="destaque"] {
    background: var(--afty-destaque);
    color: var(--afty-fundo);
    border-color: var(--afty-destaque);
  }

  /* Foco independente de cor e sem deslocar os controles. */
  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) :focus-visible {
    outline: 2px solid var(--afty-destaque);
    outline-offset: 3px;
  }

  :is(:scope#afty-ficha, #afty-ficha#afty-ficha) :is(.afty-aba, .afty-subaba):focus-visible {
    outline-offset: -3px;
  }

  @media (hover: hover) {
    :is(:scope#afty-ficha, #afty-ficha#afty-ficha):not([data-afty-estrutura="g2"]) :is([aria-labelledby="afty-aba-acoes"], [aria-labelledby="afty-aba-pericias"]) .afty-linha:not([data-afty-alvo="sim"]):hover {
      background: var(--arcane-superficie);
      border-bottom-color: var(--afty-borda-forte);
    }

    :is(:scope#afty-ficha, #afty-ficha#afty-ficha):not([data-afty-estrutura="g2"]) [aria-labelledby="afty-aba-pericias"] .afty-linha > .afty-fontes-raiz > .afty-rolavel:hover {
      border-color: var(--afty-destaque);
      background: var(--afty-destaque-fundo);
      color: var(--afty-destaque-texto);
    }

    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-botao[data-afty-tom="destaque"]:hover:not(:disabled) {
      background: var(--afty-destaque-texto);
      border-color: var(--afty-destaque-texto);
    }
  }

  @media (min-width: 1100px) {
    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-principal > div > div:has(> .afty-nome) {
      flex: 0 1 21rem;
    }

    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-controles {
      margin-inline-start: auto;
    }
  }

  @media (min-width: 768px) {
    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo .afty-vital > div:has(> input.afty-vital-numero) {
      column-gap: 0.25rem;
      flex-wrap: wrap;
    }
  }

  @media (max-width: 767px) {
    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo {
      padding-inline: 0.35rem;
    }

    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-stat-rotulo {
      font-size: 0.6rem;
      letter-spacing: 0.035em;
    }

    /* Dois recursos por fileira liberam espaço para a ficha no celular. */
    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-principal > div:has(> .afty-vital) {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 0.4rem;
    }

    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo .afty-vital {
      padding: 0.4rem;
      min-width: 0;
    }

    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo .afty-vital > div:has(> input.afty-vital-numero) {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto auto;
      align-items: center;
      gap: 0.25rem;
    }

    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo .afty-vital-icone {
      grid-area: 1 / 1;
      width: 0.85rem;
      height: 0.85rem;
      align-self: center;
    }

    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo .afty-vital-rotulo {
      grid-area: 1 / 1 / 2 / -1;
      padding-inline-start: 1.1rem;
      font-size: 0.625rem;
    }

    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo .afty-vital-numero {
      grid-area: 2 / 1;
      min-width: 0;
      width: 100%;
      font-size: 1.25rem;
      text-align: start;
    }

    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo .afty-vital .afty-base > :is(.afty-fontes-raiz, .afty-vital-max) {
      grid-area: 2 / 2;
    }

    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo .afty-vital .afty-base > span:has(> .afty-passo) {
      grid-area: 2 / 3;
    }

    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo .afty-vital-temp {
      grid-column: 1 / -1;
      justify-self: end;
    }
  }

  /* A densidade compacta reduz espaço, sem sacrificar os nomes. */
  :is(:scope#afty-ficha, #afty-ficha#afty-ficha)[data-afty-densidade="compacta"]:not([data-afty-estrutura="g2"]) [aria-labelledby="afty-aba-pericias"] .afty-linha {
    min-height: 2rem;
    padding-block: 0.15rem;
  }

  /* Em telas muito estreitas, os passos ganham uma fileira própria.
     O campo numérico conserva espaço para valores de três ou quatro dígitos. */
  @media (max-width: 359px) and (pointer: coarse) {
    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) .afty-cabecalho-conteudo .afty-vital .afty-base > span:has(> .afty-passo) {
      grid-area: 3 / 1 / 4 / -1;
      justify-self: end;
    }
  }

  @media (pointer: coarse) {
    :is(:scope#afty-ficha, #afty-ficha#afty-ficha):not([data-afty-estrutura="g2"]) [aria-labelledby="afty-aba-pericias"] :is(.afty-linha > .afty-fontes-raiz > .afty-rolavel, .afty-atributo-mod) {
      min-width: 44px;
      min-height: 44px;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) *,
    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) *::before,
    :is(:scope#afty-ficha, #afty-ficha#afty-ficha) *::after {
      animation: none !important;
      transition: none !important;
      scroll-behavior: auto !important;
    }
  }
}
